/* ============================================
   POPOVER COMPONENT
   Contextual overlay panel
   ============================================ */

.ds-popover {
  position: relative;
  display: inline-flex;
}

/* ============================================
   TRIGGER
   ============================================ */

.ds-popover__trigger {
  display: inline-flex;
  cursor: pointer;
}

/* ============================================
   PANEL
   ============================================ */

.ds-popover__panel {
  z-index: var(--layer-dropdown);
  min-width: 200px;
  padding: var(--padding-400); /* 16px */
  border: var(--border-025) solid var(--color-bg-container-border);
  border-radius: var(--radius-200); /* 8px */
  /* Page background, not container: the container fill is semi-transparent
     in dark mode, and a floating panel must not show text through itself */
  background-color: var(--color-bg-page-primary);
  /* A panel that sets its own fill sets its own ink, as every floating
     panel in the family does: inherited from a host with no body colour, a
     dark-mode panel read black on black. */
  color: var(--color-text-primary);
  box-shadow: var(--shadow-floating);

  /* Hidden by default. display:none keeps the closed panel out of the tab
     order and accessibility tree AND out of the page's scrollable overflow —
     a min-width 200px panel on an edge-adjacent trigger would otherwise add
     horizontal scroll while invisible (see Tooltip, where the leak was
     found). allow-discrete holds the panel through the exit fade,
     @starting-style below supplies the entry frame; browsers without those
     skip the fades but open and close correctly. */
  display: none;
  opacity: 0;
  pointer-events: none;
  transform: scale(0.96);
  transition-property: opacity, transform, display;
  transition-duration: var(--motion-duration-base);
  transition-timing-function: var(--motion-ease-standard);
  transition-behavior: allow-discrete;
}

.ds-popover__panel--open {
  display: block;
  opacity: 1;
  pointer-events: auto;
  transform: scale(1);
}

/* Entry state for the display flip: a panel arriving from display:none has
   no prior computed style, so this supplies the fade's starting frame. */
@starting-style {
  .ds-popover__panel--open {
    opacity: 0;
    transform: scale(0.96);
  }
}

/* ============================================
   POSITION
   The shared anchored-position behaviour
   (src/behaviors/useAnchoredPosition.ts) makes the panel fixed and sets
   where it sits: on the preferred side, flipped when that side has no room,
   shifted to stay on screen. The panel grows from the trigger's side of it,
   keyed on the side it landed on.
   ============================================ */

.ds-popover__panel[data-side='bottom'] {
  transform-origin: top left;
}

.ds-popover__panel[data-side='top'] {
  transform-origin: bottom left;
}

.ds-popover__panel[data-side='left'] {
  transform-origin: top right;
}

.ds-popover__panel[data-side='right'] {
  transform-origin: top left;
}

/* ============================================
   SIZE — COMPACT
   ============================================ */

/* The size class rides on the panel element itself, so this is a plain
   compound selector — a descendant form would never match */
.ds-popover--compact {
  padding: var(--padding-200); /* 8px */
  min-width: 160px;
}

/* ============================================
   SURFACE — MENU
   DropdownMenu's own panel, for a popover that sits among menus: its
   inset, border and corner. Its rows, headings and separators are the
   content's to draw, on the menu's measures.
   ============================================ */

.ds-popover__panel--menu,
.ds-popover--compact.ds-popover__panel--menu {
  padding: var(--padding-100);
  border-color: var(--color-input-border-primary);
  border-radius: var(--radius-300);
}

'use client';

import React, { useState, useRef, useEffect, useCallback } from 'react';
import { useLayer } from '../../behaviors/useLayer';
import { useAnchoredPosition } from '../../behaviors/useAnchoredPosition';
import { MOTION_HOVER_HIDE_DELAY_MS } from '../../tokens/motion';
import './Popover.css';

type PopoverOwnProps = {
  /** Trigger element */
  children: React.ReactNode;
  /**
   * Popover content. Replaces the native `content` attribute, which only
   * means something on a `<meta>` element.
   */
  content: React.ReactNode;
  /** Component size */
  size?: 'default' | 'compact';
  /**
   * The panel's surface. `panel` (the default) is the content panel: a
   * 16px inset and the container border. `menu` is DropdownMenu's own
   * surface (its 4px inset, input border and corner), for a popover that
   * sits among menus and should read as one of them, such as a table
   * toolbar's sort or column panel.
   */
  surface?: 'panel' | 'menu';
  /** Preferred position. `left` and `right` are screen sides; `start` and `end` follow the reading direction, so `end` opens to the right in English and to the left in Arabic. */
  position?: 'top' | 'bottom' | 'left' | 'right' | 'start' | 'end';
  /** Which edge of the trigger the panel lines up with, on the top and bottom sides. `start` and `end` follow the reading direction. Defaults to `start`. */
  align?: 'start' | 'end';
  /** Trigger mode */
  trigger?: 'click' | 'hover';
  /** Whether the popover is open (controlled mode) */
  open?: boolean;
  /** Whether the popover starts open when uncontrolled */
  defaultOpen?: boolean;
  /** Callback when open state changes */
  onOpenChange?: (open: boolean) => void;
  /** Accessible label for the trigger and the panel; the panel is named "Popover" when it is omitted */
  ariaLabel?: string;
  /** Additional CSS classes for the popover's root wrapper, which holds the trigger and the panel */
  className?: string;
};

export interface PopoverProps
  extends PopoverOwnProps,
    Omit<React.ComponentPropsWithoutRef<'div'>, keyof PopoverOwnProps> {}

/**
 * Whether an element may legally carry aria-expanded / aria-haspopup.
 * Intrinsic tags are checked against the interactive set; a custom component
 * is assumed to render a real control (every component in this library
 * spreads unrecognised props onto its primary node).
 */
const INTERACTIVE_TAGS = new Set(['button', 'a', 'input', 'select', 'textarea', 'summary']);
const canCarryPopoverSemantics = (el: React.ReactElement): boolean =>
  typeof el.type === 'string' ? INTERACTIVE_TAGS.has(el.type) : true;

/**
 * Popover component for contextual overlays.
 * Wraps a trigger element and displays content in a
 * positioned panel. Supports click and hover triggers.
 * Dismissal goes through the shared layer stack (src/behaviors/useLayer):
 * Escape closes it before anything beneath it, and in click mode a press
 * outside closes it without closing a Dialog it sits in.
 */
export const Popover = React.forwardRef<HTMLDivElement, PopoverProps>(
  (
    {
      children,
      content,
      size = 'default',
      surface = 'panel',
      position = 'bottom',
      align = 'start',
      trigger = 'click',
      open: controlledOpen,
      defaultOpen = false,
      onOpenChange,
      ariaLabel,
      className = '',
      onMouseEnter,
      onMouseLeave,
      ...rest
    },
    ref,
  ) => {
    const [internalOpen, setInternalOpen] = useState(defaultOpen);
    const containerRef = useRef<HTMLDivElement>(null);
    const triggerRef = useRef<HTMLDivElement>(null);
    const panelRef = useRef<HTMLDivElement>(null);
    const hoverTimeoutRef = useRef<ReturnType<typeof setTimeout>>(undefined);

    const setContainerRef = (node: HTMLDivElement | null) => {
      containerRef.current = node;
      if (typeof ref === 'function') ref(node);
      else if (ref) ref.current = node;
    };

    const isControlled = controlledOpen !== undefined;
    const isOpen = isControlled ? controlledOpen : internalOpen;

    const setOpen = useCallback(
      (next: boolean) => {
        if (!isControlled) {
          setInternalOpen(next);
        }
        onOpenChange?.(next);
      },
      [isControlled, onOpenChange],
    );

    useEffect(() => {
      return () => clearTimeout(hoverTimeoutRef.current);
    }, []);

    useLayer({
      open: isOpen,
      onDismiss: () => setOpen(false),
      dismissOnOutsidePress: trigger === 'click',
      getElements: () => [containerRef.current],
    });

    const handleClick = () => {
      if (trigger === 'click') {
        setOpen(!isOpen);
      }
    };

    const handleMouseEnter = (event: React.MouseEvent<HTMLDivElement>) => {
      onMouseEnter?.(event);
      if (trigger === 'hover') {
        clearTimeout(hoverTimeoutRef.current);
        setOpen(true);
      }
    };

    const handleMouseLeave = (event: React.MouseEvent<HTMLDivElement>) => {
      onMouseLeave?.(event);
      if (trigger === 'hover') {
        hoverTimeoutRef.current = setTimeout(() => setOpen(false), MOTION_HOVER_HIDE_DELAY_MS);
      }
    };

    // The panel is placed against the trigger by the shared anchored-position
    // behaviour: fixed, so a scroll container cannot clip it, on the preferred
    // side, flipped when that side has no room, and shifted to stay on screen.
    useAnchoredPosition({
      open: isOpen,
      anchorRef: triggerRef,
      panelRef,
      side: position,
      align,
      gapProperty: '--gap-050',
    });

    const baseClass = 'ds-popover';
    const sizeClass = `${baseClass}--${size}`;
    const positionClass = `${baseClass}__panel--${position}`;
    const openClass = isOpen ? `${baseClass}__panel--open` : '';

    const containerClasses = [baseClass, className].filter(Boolean).join(' ');
    const surfaceClass = surface === 'menu' ? `${baseClass}__panel--menu` : '';
    const panelClasses = [`${baseClass}__panel`, sizeClass, surfaceClass, positionClass, openClass]
      .filter(Boolean)
      .join(' ');

    return (
      <div
        {...rest}
        className={containerClasses}
        ref={setContainerRef}
        onMouseEnter={handleMouseEnter}
        onMouseLeave={handleMouseLeave}
      >
        {/*
          The trigger content is consumer-supplied and is normally already a
          control. Putting role="button" on the wrapper nested one interactive
          element inside another — instead, clone the popover semantics onto the
          real control, and only synthesise a button when there is nothing to
          clone onto.
        */}
        <div ref={triggerRef} className={`${baseClass}__trigger`} onClick={handleClick}>
          {React.isValidElement(children) && canCarryPopoverSemantics(children) ? (
            React.cloneElement(children as React.ReactElement<Record<string, unknown>>, {
              'aria-expanded': isOpen,
              'aria-haspopup': 'dialog',
              ...(ariaLabel ? { 'aria-label': ariaLabel } : {}),
            })
          ) : trigger === 'click' ? (
            <button
              type="button"
              aria-expanded={isOpen}
              aria-haspopup="dialog"
              aria-label={ariaLabel}
            >
              {children}
            </button>
          ) : (
            children
          )}
        </div>

        <div
          ref={panelRef}
          className={panelClasses}
          role="dialog"
          // role="dialog" requires an accessible name.
          aria-label={ariaLabel || 'Popover'}
          aria-hidden={!isOpen}
        >
          {content}
        </div>
      </div>
    );
  },
);

Popover.displayName = 'Popover';
